		"vega-lite/point_quantile_quantile": {
			"src": "vega-lite/examples/specs/point_quantile_quantile.vl.json",
			"spec": {
				"$schema": "https://vega.github.io/schema/vega-lite/v6.json",
				"data": {
					"url": "data/normal-2d.json"
				},
				"transform": [
					{
						"quantile": "u",
						"step": 0.01,
						"as": [
							"p",
							"v"
						]
					},
					{
						"calculate": "quantileUniform(datum.p)",
						"as": "unif"
					},
					{
						"calculate": "quantileNormal(datum.p)",
						"as": "norm"
					}
				],
				"hconcat": [
					{
						"mark": "point",
						"encoding": {
							"x": {
								"field": "unif",
								"type": "quantitative"
							},
							"y": {
								"field": "v",
								"type": "quantitative"
							}
						}
					},
					{
						"mark": "point",
						"encoding": {
							"x": {
								"field": "norm",
								"type": "quantitative"
							},
							"y": {
								"field": "v",
								"type": "quantitative"
							}
						}
					}
				]
			}
		},
		"vega-lite/layer_point_line_regression": {
			"src": "vega-lite/examples/specs/layer_point_line_regression.vl.json",
			"spec": {
				"$schema": "https://vega.github.io/schema/vega-lite/v6.json",
				"data": {
					"url": "data/movies.json"
				},
				"layer": [
					{
						"mark": {
							"type": "point",
							"filled": true
						},
						"encoding": {
							"x": {
								"field": "Rotten Tomatoes Rating",
								"type": "quantitative"
							},
							"y": {
								"field": "IMDB Rating",
								"type": "quantitative"
							}
						}
					},
					{
						"mark": {
							"type": "line",
							"color": "firebrick"
						},
						"transform": [
							{
								"regression": "IMDB Rating",
								"on": "Rotten Tomatoes Rating"
							}
						],
						"encoding": {
							"x": {
								"field": "Rotten Tomatoes Rating",
								"type": "quantitative"
							},
							"y": {
								"field": "IMDB Rating",
								"type": "quantitative"
							}
						}
					},
					{
						"transform": [
							{
								"regression": "IMDB Rating",
								"on": "Rotten Tomatoes Rating",
								"params": true
							},
							{
								"calculate": "'R²: '+format(datum.rSquared, '.2f')",
								"as": "R2"
							}
						],
						"mark": {
							"type": "text",
							"color": "firebrick",
							"x": "width",
							"align": "right",
							"y": -5
						},
						"encoding": {
							"text": {
								"type": "nominal",
								"field": "R2"
							}
						}
					}
				]
			}
		},
